BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"dca-q1": {"why_asked": "DCA の Orchestration 領域では可用性設計の理解が問われる。マネージャー障害時に「既存タスクの継続」と「新規スケジューリング機能」を混同し、片方が止まれば全部止まると誤解しやすい。またワーカーは指示がなければ自動昇格しないことも、Kubernetes 等の自己修復イメージから誤って類推されやすい点。"}, "dca-q2": {"why_asked": "ローリングアップデートの各フラグの意味を正確に区別できるかが問われる。--update-parallelism を「レプリカ総数の変更」と取り違えたり、--update-delay を「全体完了後の待機」と誤解する受験者が多く、無停止更新の設計に直結する知識のため出題される。"}, "dca-q3": {"why_asked": "Swarm のノード配置制約フラグは Kubernetes の nodeSelector と機能が似ているため、k8s 経験者ほど --node-selector のような存在しないフラグ名を選びがち。正しいフラグ名と node.labels.KEY==VALUE という書式を正確に覚えているかを試す典型問題。"}, "dca-q4": {"why_asked": "global と replicated はサービス設計の起点となる基本二択で、DCA の Orchestration 領域の頻出テーマ。自動スケーリングの有無やノード種別の制限と誤って結びつけやすく、配置ロジックそのものの違いだけを正確に理解しているかを確認する狙いがある。"}, "dca-q5": {"why_asked": "Compose/Stack ファイルの起動順序制御は実務で頻発するDB待ちの設定ミスに直結する。depends_on は systemd の after/requires と概念が似ているため、システム管理経験者ほど存在しないキー名と混同しやすく、正しいキー名の暗記を試す出題。"}, "dca-q6": {"why_asked": "docker service scale の構文は docker service update --replicas と同じ結果を生む別コマンドであり、この二重性が受験者を混乱させる。存在しないサブコマンド（resize、set）を紛れ込ませることで、正式なCLI構文を正確に覚えているかを試している。"}, "dca-q7": {"why_asked": "マルチステージビルドは docker buildx のマルチプラットフォームビルドやレイヤーキャッシュと名前・目的が紛らわしく、本来の狙い（最終イメージから不要なビルド道具を除いて軽量化すること）を正確に理解しているかを確認するために出題される。"}, "dca-q8": {"why_asked": "レイヤーキャッシュの無効化条件はCIのビルド時間に直結する実務上重要な知識。変わりやすいファイルを先にCOPYしてしまうとキャッシュが台無しになるため、Dockerfileの命令順序がキャッシュ効率にどう影響するかを理解しているかを試す定番の出題テーマ。"}, "dca-q9": {"why_asked": "プライベートレジストリへのpushはログイン・タグ付け・pushの3手順すべてが揃って初めて成功する。docker push に --registry のような存在しないフラグがあると誤解したり、タグ付けだけで認証なしにpushできると誤解しやすいため、正しい手順の全体像を問う出題。"}, "dca-q10": {"why_asked": "本番運用でのイメージ固定はDCAのセキュリティ・信頼性領域の重要テーマ。タグは書き換え可能でダイジェストは不変という違いを、高速化やセキュリティアップデートの自動取得など無関係な効能と混同させる選択肢で正確な理解を試している。"}, "dca-q11": {"why_asked": "ENTRYPOINT と CMD の組み合わせルールはDockerfile設計で最も誤解されやすいポイントの一つ。docker run 時の引数がどちらを上書きするかを逆に覚えている受験者が多く、Image Creation 領域の定番の出題テーマになっている。"}, "dca-q12": {"why_asked": "docker image inspect は存在しないサブコマンド（show、describe）や docker image ls --verbose のような紛らわしい構文と対比されやすく、イメージのメタデータを調べる正しいコマンドを正確に覚えているかを確認する出題。"}, "dca-q13": {"why_asked": "ストレージドライバーはDockerの歴史的な変遷（aufs→devicemapper→overlay2）を伴うテーマで、古い資料や環境の記憶のまま非推奨のドライバーを選んでしまう受験者がいるため、現行の推奨ドライバーを正確に知っているかを試す。"}, "dca-q14": {"why_asked": "デーモン設定ファイルのパスは、クライアント側の認証情報ファイル（~/.docker/config.json）などユーザーディレクトリ配下の設定と混同されやすい。システム全体に効くデーモン設定と個人設定の置き場所の違いを正確に区別できるかを試す。"}, "dca-q15": {"why_asked": "Installation and Configuration領域で、systemd による自動起動設定は実際のサーバ構築で必須の操作。enable（次回起動時からの自動起動）と start（今すぐ起動）を1コマンドでまとめて行う --now オプションを知っているかどうかが、旧来の service コマンドとの混同を含めて問われる。"}, "dca-q16": {"why_asked": "docker context はビルドコンテキスト（docker build時に送るファイル範囲）と名前が似ているため、両者の役割を取り違える受験者が多い。複数ホスト管理という実務上重要な機能を、名前の類似から生じる誤解と切り分けて理解しているかを試す。"}, "dca-q17": {"why_asked": "Mac/Windows で使われる Docker Desktop の内部VMの制約は、Linux上のDocker Engineと同一視してしまうと誤った運用設計につながる。企業導入時に「VM内部を自由にいじれる」と誤解しないための、環境差の正確な理解を試す出題。"}, "dca-q18": {"why_asked": "default bridge（docker0）と自作のuser-defined bridgeは似ているようで、コンテナ名によるDNS解決の可否という重要な差がある。この違いを知らずにdefault bridgeでIP直書き通信をしてトラブルになるケースが多く、Networking領域の最重要ポイントの一つ。"}, "dca-q19": {"why_asked": "-p のポートバインド書式でIPアドレスを省略すると全インターフェースに公開されてしまい、意図せず外部に晒す事故につながる。IP:HostPort:ContainerPort という3フィールドの書式を正確に理解しているかを、存在しない --bind 等のフラグと対比して試す。"}, "dca-q20": {"why_asked": "オーバーレイネットワークは複数ホストにまたがる通信を実現するが、その前提としてSwarmモードの内蔵Raftストアによる状態同期が必須である点が見落とされやすい。同一LANや静的IPなど無関係な条件と混同させることで、正しい前提条件の理解を試している。"}, "dca-q21": {"why_asked": "--network host はコンテナのネットワーク分離をなくす設定であり、名前から「外部から隔離される」と誤解する受験者がいる。分離をなくす代わりにポートマッピングが不要になる、というトレードオフをSecurity/Networking両方の観点から正確に理解しているかを試す。"}, "dca-q22": {"why_asked": "docker network inspect はコンテナ間の疎通トラブルを調べる際の第一手だが、パケットログやファイアウォールルールなど他ツール（tcpdump、iptables）の役割と混同されやすい。inspectコマンドで実際に得られる情報の範囲を正確に把握しているかを試す。"}, "dca-q23": {"why_asked": "非rootでのコンテナ実行はSecurity領域の基本対策であり、Dockerfileの USER 命令を正しく使えるかが問われる。存在しない PRIVILEGE 命令や --non-root フラグと対比することで、正確な構文知識を確認する狙いがある。"}, "dca-q24": {"why_asked": "ケーパビリティの最小化は最小権限の原則に基づくセキュリティ対策の柱で、--cap-drop ALL してから必要な分だけ --cap-add するという手順が実務の定石。存在しない --security-opt no-capabilities 等の紛らわしい選択肢と区別できるかを試している。"}, "dca-q25": {"why_asked": "Docker Content Trust は「信頼」という言葉の抽象度が高く、TLS暗号化やレイヤー暗号化など全く別のセキュリティ機能と混同されやすい。DCTが検証するのはあくまでイメージの署名（出所の正当性）であることを正確に理解しているかを試す、サプライチェーンセキュリティの出題。"}, "dca-q26": {"why_asked": "--read-only はコンテナの堅牢化で頻出のオプションだが、存在しない --immutable のような直感的なフラグ名の選択肢に惑わされやすい。正確なフラグ名の暗記と、書き込みが必要な箇所を tmpfs 等で別途開ける運用上の理解を合わせて試す。"}, "dca-q27": {"why_asked": "seccomp はカーネルへのシステムコールを制限する仕組みだが、メモリ制限やネットワーク暗号化、脆弱性スキャンなど他のセキュリティ機能と名前の抽象度から混同されやすい。攻撃対象を減らすための具体的な仕組みを正確に区別できるかを試す。"}, "dca-q28": {"why_asked": "ボリュームとバインドマウントはどちらも「ホストの永続化領域を使う」点で似ているため、管理主体（Docker管理か、ホストの任意パスか）や削除タイミングの違いが混同されやすい。Storage and Volumes領域で最も基礎的かつ頻出のテーマ。"}, "dca-q29": {"why_asked": "複数コンテナでの永続データ共有は実務で頻繁に必要になる操作で、同じボリューム名を指定するだけで共有できるというシンプルな仕組みを、docker cp によるコピーやシンボリックリンクなど遠回りな方法と区別して理解できているかを試す。"}, "dca-q30": {"why_asked": "--tmpfs はメモリ上に一時領域を作る特殊なマウントで、通常のボリュームやバインドマウントとは永続性の性質が正反対（コンテナ終了で消える）である点が問われる。存在しない --ramdisk 等のフラグ名との区別も含めた出題。"}, "dca-q31": {"why_asked": "docker volume prune はディスク容量を圧迫する未使用ボリュームの一括削除という実務でよく使う操作。docker system prune など類似の掃除コマンドとスコープが異なる点、および存在しない volume rm --all 等の構文と区別できるかを試す。"}, "dca-q32": {"why_asked": "COPY と ADD はどちらもファイルをイメージに入れる命令で機能が重なって見えるが、ADD のURL取得・tar自動展開という余分な機能が意図しない挙動を招くことがある。ベストプラクティス（基本はCOPY）の理由を理解しているかを試すDockerfile設計の定番出題。"}, "dca-q33": {"why_asked": "ARG と ENV はどちらも「変数」だが有効範囲（ビルド時のみか、実行時も残るか）が異なり、これを取り違えるとビルド時だけ必要な値が実行時に漏れて残ったり、逆に実行時に必要な設定が消えたりする。ARGの値がビルド履歴に残る点はシークレット管理の事故にも直結するため出題される。"}, "dca-q34": {"why_asked": "RUN/CMD/ENTRYPOINTのexec形式とshell形式は見た目が似ていて挙動の違いに気づきにくい。特にshell形式ではシグナルがシェル経由になりコンテナのメインプロセスに正しく届かないことがあり、Orchestration領域での正常終了・再起動の挙動理解にも関わる出題。"}, "dca-q35": {"why_asked": ".dockerignore は .gitignore と役割が似ているため混同されがちだが、対象はビルドコンテキスト（docker buildに送られるファイル群）であり、これを使わないと.envなどの機密情報が誤ってイメージに焼き込まれる事故につながる。セキュリティと軽量化の両面から出題される。"}, "dca-q36": {"why_asked": "docker commit は動くコンテナから直接イメージを作れる手軽さがある一方、どんな操作でそのイメージが作られたかが記録されず再現性がない。Dockerfileによる宣言的なビルドが推奨される理由（再現性・チーム共有）を理解しているかを試すImage Creation領域の出題。"}, "dca-q37": {"why_asked": "HEALTHCHECK は「コンテナが起動している」ことと「中のアプリが正常に動いている」ことの違いを検知する仕組みで、この区別ができていないと障害を見逃す。ホスト監視や1回限りの初期化処理と誤解しやすいため、正確な動作理解を試す。"}, "dca-q38": {"why_asked": "docker save/load と docker export/import は名前も出力形式も似ているため混同されやすい。saveがイメージ全体（レイヤー構造・タグ）を保存するのに対し、exportはコンテナの現在のファイルシステムを履歴なしで書き出すという本質的な違いを正確に理解しているかを試す。"}, "dca-q39": {"why_asked": "latest タグは名前から「常に最新の安定版」を意味すると誤解されがちだが、実際は単なる可変のタグに過ぎず、pullごとに中身が変わりうる。本番デプロイの再現性を損なう典型的な落とし穴として、Image Creation and Registry領域で必ず問われるテーマ。"}, "dca-q40": {"why_asked": "イメージレイヤーが読み取り専用でありコンテナ実行時に書き込み可能な層が上に乗る仕組み（Copy-on-Write）は、ディスク効率とイメージの安全な共有の土台になる。RUN命令の&&チェーンが1レイヤーにまとまる点も含め、レイヤー構造の基本理解を試す頻出テーマ。"}, "dca-q41": {"why_asked": "image prune と system prune はどちらも「不要物の削除」という点で似ているが、削除対象の範囲（イメージのみか、コンテナ・ネットワーク・キャッシュまで含むか）が大きく異なる。特にsystem pruneがボリュームを既定では削除しない点は、データ消失事故を防ぐ実務上重要な知識として出題される。"}, "dca-q42": {"why_asked": "マルチアーキ配布はCI/CDでイメージを公開する実務の定番作業なので、DCA試験のImage Creationドメインで狙われやすい。普通のdocker buildで--platformを複数指定すれば足りると誤解したり、buildxとdocker manifestの役割を混同したりする受験者が多い。"}, "dca-q43": {"why_asked": "FROM scratchはイメージの軽量化・攻撃面削減という本番運用の重要テーマに直結するため出題されやすい。名前から「Ubuntuの別名」「特殊なテスト環境」などと誤解しやすく、静的バイナリという前提知識とセットで正しく理解しているかが問われる。"}, "dca-q44": {"why_asked": "非rootでの実行はDCAのSecurityドメインで頻出の基本対策で、コンテナが乗っ取られたときの被害範囲を左右する重要な設定。USER命令をホストのユーザー管理やファイル所有者変更と混同しやすい点が狙われる。"}, "dca-q45": {"why_asked": "docker image inspectとdocker psはどちらも「調査系コマンド」として似た場面で使われるため、確認できる情報の境界を正確に区別できるかがDCAの運用トラブルシューティング力として問われる。"}, "dca-q46": {"why_asked": "BuildKitはDocker 18.09以降のデフォルトビルドエンジンであり、従来ビルダーとの違い（並列化・キャッシュ改善・--secret）を理解しているかがImage Creationドメインの実務知識として問われる。選択肢が実際の利点を正反対に述べる形で誤解を誘う典型的な出題パターン。"}, "dca-q47": {"why_asked": "コンテナとVMの違いはDCA全体の土台となる基礎概念で、Installation and Configurationドメインの出発点。カーネル共有ゆえの「軽さ」と「分離の弱さ」がトレードオフの表裏であることを理解しているかが、後続のセキュリティ・ネットワーク問題を理解する前提になる。"}, "dca-q48": {"why_asked": "名前空間とcgroupsはコンテナの隔離とリソース制限を支える2大カーネル機能で、DCA試験の基礎理論として繰り返し問われる。iptablesやOverlayFS、systemdなど他のLinux機能と役割を混同しないかが狙われる。"}, "dca-q49": {"why_asked": "--memoryはリソース制限の基本フラグだが、--mem-limitや--cgroup-memoryなど存在しない似た名前のフラグを選ばせる出題が多く、正確なCLI構文の記憶がDCA試験では重視される。"}, "dca-q50": {"why_asked": "daemon.jsonはDockerデーモン全体に効く永続設定ファイルで、docker runの個別引数やDockerfile、Composeの設定と役割が異なる。この設定範囲の違いを正確に区別できるかがInstallation and Configurationドメインで問われる。"}, "dca-q51": {"why_asked": "ログローテーション未設定によるディスク枯渇は実運用で頻発する障害パターンであり、DCAではjson-fileドライバーのmax-size/max-fileという具体的な対策設定を知っているかが実務力として問われる。"}, "dca-q52": {"why_asked": "docker contextは名前が「ビルドコンテキスト」と似ているため混同しやすく、この名前の罠を見抜けるかが狙われる。複数環境のDockerデーモンを切り替える運用知識としてDCAで問われる。"}, "dca-q53": {"why_asked": "ディスク逼迫時に最初に叩く調査コマンドとして実務でよく使われるため、docker system dfが何を表示し何を表示しないか（CPU/メモリはdocker stats、プロセスはdocker top）という役割分担の理解がDCAで問われる。"}, "dca-q54": {"why_asked": "--cpusはCPUリソース制限の基本フラグで、--cpu-countや--cpu-limitなど存在しないフラグ名との弁別、および--cpu-shares（優先度）との役割の違いを正確に理解しているかがDCAで問われる。"}, "dca-q55": {"why_asked": "デフォルトブリッジではコンテナ名の名前解決ができないという制約は「コンテナ名でつながらない」という実際のトラブルの典型原因であり、カスタムブリッジへの切り替えを判断する実務知識としてDCAのNetworkingドメインで頻出。"}, "dca-q56": {"why_asked": "hostネットワークモードはポートマッピング不要でホストのネットワーク名前空間を共有するという特殊な挙動があり、-Pによる自動マッピングやnoneモードの完全隔離と混同しやすい点がDCAで狙われる。"}, "dca-q57": {"why_asked": "noneネットワークはネットワーク隔離の中でも最も厳格なモードで、hostモード（共有）との対比、また同一コンテナ内のループバック通信は生きている点など細部の理解がDCAで問われる。"}, "dca-q58": {"why_asked": "コンテナ名で通信できる仕組み（組み込みDNSサーバー）はComposeやSwarmでのサービス間通信の土台であり、この仕組みを古い--link機能の/etc/hosts自動記述と混同しないかがDCAのNetworkingドメインで問われる。"}, "dca-q59": {"why_asked": "-pと-Pは大文字小文字だけの違いに見えて動作がまったく異なるため、この紛らわしさそのものがDCAの出題ポイントになりやすい。本番のポート固定運用とテスト時の自動割り当ての使い分けという実務判断にも直結する。"}, "dca-q60": {"why_asked": "Overlayネットワークは単一ホスト内のブリッジネットワークとは異なりSwarmのマルチホスト構成で使われるため、DCAのOrchestrationドメインで用途の違いを正確に区別できるかが問われる。"}, "dca-q61": {"why_asked": "Macvlanは物理ネットワークに直接コンテナを参加させるという他のネットワークドライバーにはない特殊な動作をするため、Overlayやbridgeとの違い、暗号化機能の有無などの混同を突く出題がされやすい。"}, "dca-q62": {"why_asked": "SwarmのingressネットワークによるルーティングメッシュはDCAのOrchestrationドメインの核心的な仕組みで、「どのノードにアクセスしてもサービスに届く」という一見不思議な挙動の裏側を理解しているかが問われる。ファイアウォールやサービス間内部通信用のoverlayと役割を混同しないことも狙われる。"}, "dca-q63": {"why_asked": "コンテナが外部通信できる仕組み（SNAT/MASQUERADE）はネットワークトラブルシュートの前提知識であり、DNAT（受信方向のポートマッピング）との方向の違いを正確に区別できるかがDCAで問われる。"}, "dca-q64": {"why_asked": "名前空間とcgroupsは「隔離」と「リソース制限」という異なる役割を持つため、この境界線（ディスクI/O帯域幅はcgroups側）を正確に理解しているかがDCAの基礎知識として繰り返し問われる。"}, "dca-q65": {"why_asked": "--cap-add/--cap-dropは最小権限の原則を実践する具体的な手段であり、--privilegedとの権限範囲の違い（個別ケイパビリティか全権限か）を理解しているかがDCAのSecurityドメインで問われる。"}, "dca-q66": {"why_asked": "--read-onlyはイミュータブルインフラを実現する基本設定で、存在しない類似フラグ名（--immutable等）との弁別、およびtmpfsとの組み合わせによる書き込み領域確保という実務パターンがDCAで問われる。"}, "dca-q67": {"why_asked": "Swarmのsecretは機密情報を安全に配布する仕組みで、環境変数（docker inspectで平文が見える）との違いや、暗号化・スコープ・マウント方式の細部がDCAのSecurityドメインで問われる。"}, "dca-q68": {"why_asked": "seccompはコンテナのデフォルトセキュリティ機構の一つで、CPU制限やネットワーク暗号化、ファイルシステムアクセス制御（AppArmor/SELinuxの領域）と役割を混同しないかがDCAで問われる。"}, "dca-q69": {"why_asked": "--privilegedは単なるroot実行よりもはるかに広範な権限（capabilities・デバイス・seccomp・AppArmorの解除）を与えるため、その危険性の正確な理解がDCAのSecurityドメインで重視される。"}, "dca-q70": {"why_asked": "Docker Content Trustは署名検証によるサプライチェーンセキュリティの仕組みで、暗号化と署名検証の違い、および存在しない環境変数名（DOCKER_TRUST_ALL）との弁別がDCAで問われる。"}, "dca-q71": {"why_asked": "ボリューム・バインドマウント・tmpfsの使い分けはStorage and Volumesドメインの根幹であり、管理主体（Docker管理かホスト直結かメモリのみか）と永続性の違いを正確に理解しているかが実務のデータ管理判断に直結するため問われる。"}, "dca-q72": {"why_asked": "名前付きボリュームと匿名ボリュームは見た目が似ていても削除時の挙動（-vオプションでの一括削除の可否）が異なり、ディスクを圧迫する消し忘れの原因にもなるため、DCAで運用上の違いが問われる。"}, "dca-q73": {"why_asked": "docker volume inspectで何がわかり何がわからないか（使用中コンテナやファイル一覧は別コマンド）を正確に切り分けられるかが、他の調査コマンドと同様にDCAで繰り返し問われるパターン。"}, "dca-q74": {"why_asked": "overlay2はDockerのデフォルトストレージドライバーであり、OverlayFSによるレイヤー構造とCopy-on-Writeの仕組みを理解しているかが、ディスク効率やイメージ共有の挙動を説明する土台としてDCAで問われる。"}, "dca-q75": {"why_asked": "Docker自体にはボリューム専用のバックアップコマンドが存在しないため、一時コンテナ経由でtarを使う標準的な回避策を知っているかという実務寄りの手順知識がDCAで問われる。"}, "dca-q76": {"why_asked": "--tmpfsは高速だが揮発性という特性を持ち、永続化が必要なバインドマウントや名前付きボリュームとの使い分けを誤ると、意図せずデータが消える事故につながるため、この違いがDCAで問われる。"}, "dca-q77": {"why_asked": "Dockerはファイルロックを提供しないため、複数コンテナで同一ボリュームを共有する構成は一見動くように見えてデータ競合のリスクを抱える。この落とし穴に気づけるかがStorage and Volumesドメインの実務判断力としてDCAで問われる。"}, "dca-q78": {"why_asked": "configとsecretは配布の仕組みが似ているため名前や用途を混同しやすく、機密性の扱い（暗号化して/run/secrets/にのみマウントするか否か）という違いを正確に理解しているかがDCAのOrchestration/Securityドメインで問われる。"}, "dca-q79": {"why_asked": "SwarmのHEALTHCHECK連動による自動復旧は「望ましい状態」への収束という宣言的オーケストレーションの核心的な挙動であり、単体docker runの--health-*（ステータス表示のみ）との違いを理解しているかがDCAで問われる。"}, "dca-q80": {"why_asked": "drainはメンテナンス作業の定番操作で、ノードの削除（docker node rm）や降格（docker node demote）など似た名前の別操作と混同しないかが、Swarm運用の実務知識としてDCAで問われる。"}, "dca-q81": {"why_asked": "constraintとplacement-prefは両方とも配置制御に使われるため名前や目的が混同されやすいが、必須条件かベストエフォートの優先度かという性質の違いを理解しているかがSwarmの可用性設計に直結するため、DCAで問われる。"}, "dca-q82": {"why_asked": "Swarmの--restart-conditionはnone/on-failure/anyの3値しか持たないが、docker run --restartで使うalwaysやunless-stoppedと誤って混同しやすいため、この値の違いを正確に覚えているかがDCAで問われる。"}, "dca-q83": {"why_asked": "--update-parallelism・--update-delay・--update-order・--update-failure-actionはどれも「update-」で始まる似た名前のオプションで、DCAではローリングアップデートの制御方法を問う定番の出題。失敗時にどうするか（pause/continue/rollback）だけがfailure-actionの役割だと区別できるかを確認する。"}, "dca-q84": {"why_asked": "Swarmのjoin-tokenはworker用とmanager用の2種類があるという設計を知らないと、誤ってmanagerトークンを外部委託先などに渡してクラスターの制御権を渡してしまう事故につながる。本番運用のセキュリティ設計として頻出する。"}, "dca-q85": {"why_asked": "Swarmサービスへの接続方式にはVIP（既定）とDNSRRの2種類があり、どちらが既定でどう動くかを混同しやすい。ロードバランシングの挙動を問うDCAのネットワーキング領域の定番論点。"}, "dca-q86": {"why_asked": "reserveとlimitは名前も並びも似ているため、「配置時の目安」と「実行時の強制上限」という役割の違いを取り違えやすい。リソース設計の実務判断に直結するため出題される。"}, "dca-q87": {"why_asked": "docker node ls・service ls・ps・statsなど似た一覧系コマンドが複数あり、それぞれ何のレイヤーの情報を見せるかを混同しやすい。DCAはこの手のコマンドの守備範囲の切り分けを頻出させる。"}, "dca-q88": {"why_asked": "autolockはディスク上のRaftデータを暗号化する機能で、ノード間通信のTLS暗号化やDocker Content Trustの署名など他のセキュリティ機能と混同されやすい。守る対象（ディスク上のデータか、通信か）の違いを見分けられるかが問われる。"}, "dca-q89": {"why_asked": "LABELはARGやENVと同じく「Dockerfileで値を定義する命令」という点で似て見えるが、動作に影響しないメタデータである点が異なる。Image Creation領域で命令ごとの役割の切り分けを問う定番。"}, "dca-q90": {"why_asked": "ONBUILDは「自分のビルド時に何かが起きる」と誤解しやすいが、実際は自分をFROMする子イメージのビルド時にだけ発火する予約命令。この発火タイミングの取り違えがDCAで繰り返し狙われる。"}, "dca-q91": {"why_asked": "EXPOSEを書けばポートが外部公開されると誤解する初学者が非常に多く、実務でも「EXPOSEしたのにアクセスできない」という典型的なハマりどころになる。実際に公開するのは-pであるという区別がDCAで重視される。"}, "dca-q92": {"why_asked": "VOLUME命令はdocker run -vによるバインドマウントと混同されやすいが、Dockerfile側の宣言はホストパスを直結するものではなく、書き込みをコンテナ層に溜めないための仕組みである点が問われる。"}, "dca-q93": {"why_asked": "docker tagは名前からイメージを複製する操作だと誤解されやすいが、実際はイメージIDという同じ実体に呼び名を増やすだけの操作。ディスク使用量やレイヤー共有の理解を問うために出題される。"}, "dca-q94": {"why_asked": "docker history・docker stats・docker psはいずれも「情報を一覧表示するコマンド」という共通点があるため守備範囲を混同しやすい。イメージのレイヤー構成を調べる場面でどのコマンドを使うべきかがDCAで問われる。"}, "dca-q95": {"why_asked": "本番用・開発用など複数のDockerfileを使い分ける実務は多く、既定のファイル名（Dockerfile）以外を指定する-fオプションの正しい書き方を知っているかが問われる。似た誤答（--nameや存在しないオプション名）に惑わされないかも確認される。"}, "dca-q96": {"why_asked": "ARMベースの開発機やクラウドインスタンドが普及したことで、マルチプラットフォームイメージの仕組み（マニフェストリストによる自動選択）を理解しているかが実務上も重要になっており、Image Managementの現代的な論点として出題される。"}, "dca-q97": {"why_asked": "docker loginの認証情報は常に安全に保管されると思い込みがちだが、credential helperが無い環境では設定ファイルに平文相当で残るというセキュリティ上の落とし穴があり、CI環境などの運用設計で重要な論点として問われる。"}, "dca-q98": {"why_asked": "--build-argを付けただけで値が使えると誤解し、Dockerfile側にARG宣言を書き忘れる事故が実務で非常に多い。値が『無視される』という挙動を正しく理解しているかが問われる。"}, "dca-q99": {"why_asked": "クラウドインスタンスなど複数のネットワークインターフェースを持つホストでSwarmを組む際、意図しないIPが自動選択されてノード間通信が失敗する事故が起きやすく、--advertise-addrで明示する必要性が実務レベルで問われる。"}, "dca-q100": {"why_asked": "dockerdへのアクセス権はホストのroot権限とほぼ同義であるという事実を軽視すると、TCP公開時の認証設定漏れが致命的な脆弱性になる。Security領域で最も実害の大きい設定ミスとして重視される。"}, "dca-q101": {"why_asked": "DOCKER_HOSTはdocker contextと役割が近いため混同されやすいが、CLIがどのデーモンに接続するかを直接指定する基本的な環境変数であり、リモート操作の基礎として問われる。"}, "dca-q102": {"why_asked": "Dockerが自動割り当てするネットワークのIPレンジが社内の他システムと衝突すると通信障害につながるため、default-address-poolsで事前に調整しておく設計判断が実務上重要であり出題される。"}, "dca-q103": {"why_asked": "live-restoreはコンテナの自動再起動ポリシーやsystemdの再起動設定と混同されやすいが、実際はデーモン自体の再起動・アップグレード中もコンテナを止めないための設定であり、無停止運用の要となる知識として問われる。"}, "dca-q104": {"why_asked": "rootlessモードとuserns-remapはどちらも「root権限を制限する」という似た目的のセキュリティ機能で名前も紛らわしいが、守る対象（デーモン自体かコンテナ内rootか）が異なる。この違いを混同しないかがSecurity領域で狙われる。"}, "dca-q105": {"why_asked": "get.docker.comのconvenience script（curl | sh）は手軽さから広く使われているが、公式ドキュメントが本番の恒常運用には推奨していないという注意点は見落とされやすく、インストール方法の選定基準として問われる。"}, "dca-q106": {"why_asked": "ネットワーク作成時にIP範囲を明示できることを知らないと、既定プールの自動割り当てに任せきりになり、社内ネットワークとの衝突を防げない。--subnet/--gatewayの基本操作としてNetworking領域で問われる。"}, "dca-q107": {"why_asked": "--add-hostはDNSサーバーの設定変更やホスト側/etc/hostsの書き換えと誤解されやすいが、実際はコンテナ内部の/etc/hostsだけに閉じたピンポイントな名前解決の仕組みであり、その適用範囲の理解が問われる。"}, "dca-q108": {"why_asked": "--network-aliasを『名前の置き換え』と誤解しやすいが、実際は既存のコンテナ名に加えて別名を追加するだけの機能。組み込みDNSによる名前解決の仕組みを正しく理解しているかがNetworking領域で問われる。"}, "dca-q109": {"why_asked": "overlayネットワークは既定でSwarmサービス専用という前提を知らないと、デバッグ用の単独コンテナを同じネットワークに接続できず困る。--attachableの役割はSwarmとネットワーキングをまたぐ実務的な論点として出題される。"}, "dca-q110": {"why_asked": "同じDockerホスト上にいれば自動的に通信できると誤解しやすいが、実際は異なるネットワークに接続されたコンテナ同士は既定で分離されている。この分離を前提にしたセキュアなネットワーク設計の理解がNetworking領域で問われる。"}, "dca-q111": {"why_asked": "--dnsはホスト全体のDNS設定や組み込みDNSの無効化と混同されやすいが、実際は指定したコンテナ単位でのみ外部名前解決先を上書きする設定であり、その適用範囲の狭さが問われる。"}, "dca-q112": {"why_asked": "seccomp・ケーパビリティ・AppArmorはいずれも『コンテナの権限を制限する仕組み』という共通点があるため一括りにされがちだが、それぞれ制限する層（システムコール・権限の種類・操作対象）が異なる。多層防御の考え方を理解しているかがSecurity領域で問われる。"}, "dca-q113": {"why_asked": "no-new-privilegesは--cap-addの禁止やネットワーク制限と混同されやすいが、実際は実行中の権限昇格だけをブロックする設定。USER命令で非rootにした効果を実行中も保証する仕組みとしてSecurity領域で問われる。"}, "dca-q114": {"why_asked": "Docker Content Trustの鍵構成（ルートキーとリポジトリキー）は、片方が漏れても被害を限定できるように役割分担されている設計であり、この鍵の階層構造を理解しているかがSecurity領域で問われる。"}, "dca-q115": {"why_asked": "脆弱性スキャンをDockerfileの構文チェックやビルド最適化ツールと混同しないよう、CVEという既知の脆弱性情報とイメージ内容を突き合わせる仕組みであるという目的の理解がSecurity領域で問われる。"}, "dca-q116": {"why_asked": "CIS Docker Benchmarkを『Docker自身が持つセキュリティ機能』と誤解しやすいが、実際は設定の堅牢さを点検するための外部の基準（チェックリスト）である。機能と点検基準の違いを区別できるかがSecurity領域で問われる。"}, "dca-q117": {"why_asked": "Swarmのノード間通信は追加の証明書設定なしに既定でTLS保護されるという事実は見落とされやすく、Docker Content Trust（イメージ署名）との役割の違いも含めてSecurity領域で問われる。"}, "dca-q118": {"why_asked": "『local』という名前から、ホスト内のフォルダしか扱えないと誤解しやすいが、実際はオプション次第でNFSなどリモート共有もマウントできる。Storage and Volumes領域でドライバー名に惑わされない理解が問われる。"}, "dca-q119": {"why_asked": ":roはホスト側のファイル権限まで変更すると誤解されやすいが、実際はコンテナ側から見た読み取り専用化にすぎない。設定ファイルなど改ざんされたくないデータを渡す場面の設計判断としてStorage領域で問われる。"}, "dca-q120": {"why_asked": "data-rootはログの保存先やDockerfileの探索場所と混同されやすいが、実際はイメージ・コンテナ・ボリュームを含むDockerの全データの保存先そのものを指す設定。ディスク容量が逼迫した本番運用での対処法として問われる。"}, "dca-q121": {"why_asked": "Docker Desktopがコンテナを内部でLinux VMを介して動かしているという構成を知らないと、バインドマウントの体感速度の遅さの原因を誤って判断してしまう。Mac/Windows開発環境特有の性能特性としてInstallation and Configuration領域で問われる。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca')
  AND q.explanation_data IS NOT NULL;

COMMIT;
